SELECT settlement_data.*,settlement_data.EXPECTED_NET_AMOUNT-settlement_data.REPORTED_NET_AMOUNT AS NET_AMOUNT_DISCREPANCY FROM
    (SELECT BATCH_ID,CURRENCY, GROSS_AMOUNT,FEE_AMOUNT,REFUND_AMOUNT,CHARGEBACK_AMOUNT,ADJUSTMENT_AMOUNT,REPORTED_NET_AMOUNT,
    GROSS_AMOUNT-FEE_AMOUNT-REFUND_AMOUNT-CHARGEBACK_AMOUNT+ADJUSTMENT_AMOUNT AS EXPECTED_NET_AMOUNT 
    FROM SARVAGYA.SETTLEMENTS) AS settlement_data;